const body = $json.body || $json;
const snapshotId = body.snapshot_id || null;
const provider = body.provider || 'mock';
const forceFallback = Boolean(body.force_fallback);
const corrId = body.correlation_id || ('corr_ai_' + Math.random().toString(36).substring(2, 10));

return [{
  json: {
    snapshot_id: snapshotId,
    provider: provider,
    force_fallback: forceFallback,
    correlation_id: corrId
  }
}];

const data = $json.data || {};
const sections = data.sections || {};
const corrId = $json.correlation_id || 'unknown';

return [{
  json: {
    workflow: 'WF06 - Grounded AI Executive Intelligence',
    status: 'SUCCESS',
    summary_id: data.summary_id,
    snapshot_id: data.snapshot_id,
    model_provider: data.model_provider,
    model_name: data.model_name,
    validation_status: data.validation_status,
    duration_ms: data.duration_ms,
    token_count: data.token_count,
    grounding_checks_passed: (data.grounding_checks || []).every(c => c.is_grounded),
    briefing: {
      business_overview: sections.business_overview,
      revenue_profitability: sections.revenue_profitability,
      order_performance: sections.order_performance,
      product_geography_insights: sections.product_geography_insights,
      detected_anomalies: sections.detected_anomalies,
      operational_observations: sections.operational_observations,
      investigation_priorities: sections.investigation_priorities || []
    },
    correlation_id: corrId
  }
}];
